CREATE OR ALTER PROCEDURE dbo.usp_PlaceOrder @CustomerID int,@ProductID int,@Quantity int,@OrderNumber int OUTPUT AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; SET @OrderNumber=NULL; IF @Quantity<=0 THROW 50001,'Quantity must be positive.',1; IF NOT EXISTS(SELECT 1 FROM dbo.Customers WHERE CustomerID=@CustomerID) THROW 50002,'Customer not found.',1; BEGIN TRY BEGIN TRAN; DECLARE @Price decimal(10,2); SELECT @Price=UnitPrice FROM dbo.Products WITH(UPDLOCK,HOLDLOCK) WHERE ProductID=@ProductID AND Stock>=@Quantity; IF @Price IS NULL THROW 50003,'Product unavailable or insufficient stock.',1; INSERT dbo.Orders(CustomerID,Status) VALUES(@CustomerID,'Pending'); SET @OrderNumber=SCOPE_IDENTITY(); INSERT dbo.OrderLines(OrderID,ProductID,Quantity,UnitPrice) VALUES(@OrderNumber,@ProductID,@Quantity,@Price); UPDATE dbo.Products SET Stock=Stock-@Quantity WHERE ProductID=@ProductID; COMMIT; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @OrderNumber=NULL; THROW; END CATCH END;
GO
CREATE OR ALTER FUNCTION dbo.fn_OrderTotalWithTax(@OrderID int) RETURNS decimal(12,2) AS BEGIN DECLARE @T decimal(12,2); SELECT @T=SUM(Quantity*UnitPrice)*1.18 FROM dbo.OrderLines WHERE OrderID=@OrderID; RETURN COALESCE(@T,0); END;
GO
CREATE OR ALTER FUNCTION dbo.fn_CustomerOrders(@CustomerID int) RETURNS TABLE AS RETURN SELECT o.OrderID,o.OrderDate,o.Status,SUM(ol.Quantity*ol.UnitPrice) Subtotal,SUM(ol.Quantity*ol.UnitPrice)*1.18 TotalWithTax FROM dbo.Orders o JOIN dbo.OrderLines ol ON ol.OrderID=o.OrderID WHERE o.CustomerID=@CustomerID GROUP BY o.OrderID,o.OrderDate,o.Status;
GO
DECLARE @N int; EXEC dbo.usp_PlaceOrder 1,102,2,@N OUTPUT; SELECT @N OrderNumber,dbo.fn_OrderTotalWithTax(@N) TotalWithTax; SELECT * FROM dbo.fn_CustomerOrders(1);